-- composition of rule kernels common_aggregate x deliminator (duckdb), template product
SELECT count(*) FROM (SELECT a1.c0 AS c0, a1.c0 AS c1 FROM t3 AS a1 WHERE (2 > ALL (SELECT a1.c0 AS c0)) INTERSECT (SELECT 17 AS c0, 10 AS c1 UNION SELECT 22 AS c0, 1 AS c1)) AS ka CROSS JOIN (SELECT 'A'::text AS c0 FROM t0 AS a1, LATERAL (SELECT '1999-12-31 23:59:59.999999+05:30'::timestamptz AS c0, a1.c1 AS c1) AS a2 EXCEPT ALL SELECT 'A'::text AS c0) AS kb;
